<?php
namespace App\Models;use App\Models\Concerns\BelongsToTenant;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\HasMany;class MenuItem extends Model{use BelongsToTenant;protected $fillable=['hotel_id','restaurant_id','menu_category_id','name','description','price','image_path','preparation_minutes','dietary_info','allergens','is_available'];protected function casts():array{return ['price'=>'decimal:2','dietary_info'=>'array','allergens'=>'array','is_available'=>'boolean'];}public function modifiers():HasMany{return $this->hasMany(MenuModifier::class);}}
